    return Array.from(panel.querySelectorAll('label')).map(l => l.textContent?.trim());
  };

  return {
    event: getPanelItems('filterpanel-accordion-panel-1'),
    itemType: getPanelItems('filterpanel-accordion-panel-3'),
    sizeRange: getPanelItems('filterpanel-accordion-panel-9'),
