      tag: curr.tagName,
      role: curr.getAttribute('role'),
      className: curr.className,
      hasOnClick: !!curr.onclick,
      events: Object.keys(curr)
    });
    curr = curr.parentElement;
  }
  return { path, outerHTML: menEl.parentElement?.outerHTML };
});
