const tabId = 583778164;

// Let's click or inspect the accordions for item type, size range, gender
const filterDetails = await browserjs(tabId, async () => {
  // Function to click accordion button if not expanded
  const expandAccordion = (id) => {
    const btn = document.getElementById(id);
    if (btn && btn.getAttribute('aria-expanded') !== 'true') {
      btn.click();
    }
  };

  expandAccordion('filterpanel-accordion-button-1'); // event
  expandAccordion('filterpanel-accordion-button-3'); // item type
  expandAccordion('filterpanel-accordion-button-9'); // size range
  expandAccordion('filterpanel-accordion-button-11'); // gender

  // Give DOM a moment
  await new Promise(r => setTimeout(r, 500));

  const getPanelItems = (id) => {
    const panel = document.getElementById(id);
    if (!panel) return [];
    return Array.from(panel.querySelectorAll('label')).map(l => l.textContent?.trim());
  };

  return {
    event: getPanelItems('filterpanel-accordion-panel-1'),
    itemType: getPanelItems('filterpanel-accordion-panel-3'),
    sizeRange: getPanelItems('filterpanel-accordion-panel-9'),
    gender: getPanelItems('filterpanel-accordion-panel-11')
  };
});

console.log(JSON.stringify(filterDetails, null, 2));

