// Let's inspect every single option in all 12 filter accordions
const allOptions = await browserjs(tabId, async () => {
  // Let's open all accordion panels
  const btns = Array.from(document.querySelectorAll('[id^="filterpanel-accordion-button-"]'));
  for (const b of btns) {
    if (b.getAttribute('aria-expanded') !== 'true') {
      b.click();
    }
  }
  await new Promise(r => setTimeout(r, 600));

  const result = {};
  for (const b of btns) {
    const id = b.getAttribute('aria-controls');
    const panel = document.getElementById(id);
    const title = b.textContent?.trim();
    if (panel) {
      result[title] = Array.from(panel.querySelectorAll('label')).map(l => l.textContent?.trim());
    }
  }
  return result;
});

console.log(JSON.stringify(allOptions, null, 2));

